describe("turn notifications", () => {
  afterEach(() => vi.unstubAllGlobals());

  let reply = () => anthropicResponse([{ type: "text", text: "Done." }], "end_turn",
      { input: 1, cacheRead: 0, cacheWrite: 0, output: 1 });
  let notification = (turn: Turn, kind: UserNotification["kind"]) => [INITIATOR_USER_ID, {
    id: expect.any(String), kind, workspaceId: turn.gadgetId, chatId: CHAT_ID, chatTitle: "Chat",
  }];

  it("tells the initiator a turn completed, but not a callback turn nobody started", async () => {
    let turn = startTurn([reply, reply]);
    await turn.requested;
    await inOverseer(turn.workspace, impl =>
        impl.deliverAgentCallback(CHAT_ID, "ping", [], OWNER_USER_ID, MODEL.id));
    turn.release();

    await turnSpans(turn, 2);
    expect(turn.notifications).toEqual([notification(turn, "taskCompleted")]);
  });

  it("does not tell anyone a spawned agent's turn completed", async () => {
    let turn = startTurn([reply], {
      initiator: { type: "gadget", id: "spawner", name: "Spawner" },
    });
    turn.release();

    await turn.session;
    expect(turn.notifications).toEqual([]);
  });

  it("sends nothing for a turn that failed", async () => {
    let turn = startTurn([() => Response.json(
        { type: "error", error: { type: "invalid_request_error", message: "bad" } },
        { status: 400 })]);
    turn.release();

    await turn.session;
    expect(turn.notifications).toEqual([]);
  });

  // The agent submits an action that waits for the user's decision while its step runs; the user
  // decides (or not) during the step, or once it is over and persisting.
  it.each([
    { state: "pending", when: "during its step", kind: "permissionRequested" },
    { state: "rejected", when: "during its step", kind: "taskCompleted" },
    { state: "rejected", when: "as its step persists", kind: "taskCompleted" },
  ] as const)("sends $kind when the awaited action is $state $when",
      async ({ state, when, kind }) => {
    let turn = startTurn([reply]);
    await turn.requested;
    await inOverseer(turn.workspace, async impl => {
      impl.storage.gatekeepers.put({
        id: 7, resourceTitle: "Repository", class: {},
        creationSpec: {
          type: "gatekeeper", vendorId: "testvendor",
          resourceUrl: "https://example.com/repo", typeUrlPattern: "https://*",
        },
      });
      await impl.submitAction(7, 1, {
        title: "Send", description: "", implementsRevert: false, awaitDecision: true,
      }, { from: "agent", chatId: CHAT_ID });
      let [record] = impl.storage.actions.list();
      let decide = () => impl.storage.actions.put({ ...record, state });
      if (when === "as its step persists") {
        let commit = impl.commitAgentStep.bind(impl);
        impl.commitAgentStep = (...args) => {
          decide();
          return commit(...args);
        };
      } else {
        decide();
      }
    });
    turn.release();

    await turn.session;
    expect(turn.notifications).toEqual([notification(turn, kind)]);
  });
});

import { describe, expect, it, vi } from "vitest";
import { withAuthRetry } from "../src/auth-retry";

type TokenRequest = { forceRefresh: boolean; staleToken?: string };

describe("withAuthRetry", () => {
  it("uses the first token without adding a stale-token hint", async () => {
    const getToken = vi.fn(async () => "current");
    const run = vi.fn(async (token: string) => `${token}-result`);

    expect(await withAuthRetry({ getToken, isAuthError: () => false, replayable: true }, run))
      .toBe("current-result");
    expect(getToken).toHaveBeenCalledOnce();
    expect(getToken).toHaveBeenCalledWith({ forceRefresh: false });
    expect(run).toHaveBeenCalledOnce();
  });

  it("passes through a first non-auth failure without refreshing", async () => {
    const failure = new Error("provider unavailable");
    const getToken = vi.fn(async () => "current");
    const run = vi.fn(async () => { throw failure; });

    await expect(withAuthRetry({ getToken, isAuthError: () => false, replayable: true }, run))
      .rejects.toBe(failure);
    expect(getToken).toHaveBeenCalledOnce();
  });

  it("refreshes with the rejected token and returns the replayed result", async () => {
    const authError = new Error("401");
    const getToken = vi.fn(async ({ forceRefresh }: TokenRequest) =>
      forceRefresh ? "fresh" : "stale");
    const run = vi.fn(async (token: string) => {
      if (token === "stale") throw authError;
      return "accepted";
    });

    expect(await withAuthRetry(
      { getToken, isAuthError: error => error === authError, replayable: true }, run))
      .toBe("accepted");
    expect(getToken).toHaveBeenNthCalledWith(2, {
      forceRefresh: true,
      staleToken: "stale",
    });
    expect(run).toHaveBeenCalledTimes(2);
  });

  it("throws the failure a twice-rejected credential ends with", async () => {
    const firstError = new Error("first 401");
    const secondError = new Error("second 401");
    const getToken = vi.fn(async ({ forceRefresh }: TokenRequest) =>
      forceRefresh ? "fresh" : "stale");
    const run = vi.fn(async (token: string) => {
      throw token === "stale" ? firstError : secondError;
    });

    // Reporting is out of scope here: `CredentialSource.run(operation, { replayable: true })`
    // owns the retry-then-report flow, with the account healing inside the rejection
    // adjudication.
    await expect(withAuthRetry({
      getToken,
      isAuthError: error => error === firstError || error === secondError,
      replayable: true,
    }, run)).rejects.toBe(secondError);
  });

  it("propagates a non-auth failure from the replay untouched", async () => {
    const authError = new Error("401");
    const providerError = new Error("provider unavailable");
    const getToken = vi.fn(async ({ forceRefresh }: TokenRequest) =>
      forceRefresh ? "fresh" : "stale");
    const run = vi.fn(async (token: string) => {
      throw token === "stale" ? authError : providerError;
    });

    await expect(withAuthRetry({
      getToken,
      isAuthError: error => error === authError,
      replayable: true,
    }, run)).rejects.toBe(providerError);
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";
import { AccessTokenCache, fetchWithAuthRetry, type AccessTokenRequest } from "../src/auth-retry";
import { getGoogleAccountProfile } from "../src/google-api";

/** A stub authority recording every request, answering with whatever token it currently holds. */
function authority(initial: string) {
  let requests: (AccessTokenRequest | undefined)[] = [];
  let stored = initial;
  let cache = new AccessTokenCache(async opts => {
    requests.push(opts);
    return { token: stored, expires: new Date(Date.now() + 3600_000) };
  });
  return {
    cache,
    requests,
    /** What a reconnect does: replace the stored token, telling no gatekeeper about it. */
    restore(token: string) { stored = token; },
  };
}

describe("AccessTokenCache", () => {
  it("answers repeat calls from the memo", async () => {
    let account = authority("tok");

    expect(await account.cache.get()).toBe("tok");
    expect(await account.cache.get()).toBe("tok");
    expect(account.requests).toHaveLength(1);
  });

  it("picks up a token stored since it memoized, without asking for a mint", async () => {
    let account = authority("narrow");
    expect(await account.cache.get()).toBe("narrow");
    account.restore("widened");

    expect(await account.cache.get()).toBe("narrow");
    expect(await account.cache.get({ reloadStored: true })).toBe("widened");

    expect(account.requests).toEqual([undefined, { reloadStored: true }]);
  });

  it("memoizes the reloaded token, so one 403 costs one round trip", async () => {
    let account = authority("narrow");
    await account.cache.get();
    account.restore("widened");
    await account.cache.get({ reloadStored: true });

    expect(await account.cache.get()).toBe("widened");
    expect(account.requests).toHaveLength(2);
  });
});

describe("fetchWithAuthRetry", () => {
  afterEach(() => {
    vi.unstubAllGlobals();
  });

  // Unlike a stream, a byte-array body survives being sent and can be replayed after a 401.
  it("replays a byte-array body once after a 401 refresh", async () => {
    let bodies: string[] = [];
    let tokens: (string | null)[] = [];
    let status = 401;
    vi.stubGlobal("fetch", async (_url: string, init: RequestInit = {}) => {
      bodies.push(new TextDecoder().decode(init.body as Uint8Array));
      tokens.push(new Headers(init.headers).get("Authorization"));
      let current = status;
      status = 200;
      return new Response("{}", { status: current });
    });
    let minted = 0;
    let response = await fetchWithAuthRetry(
      "https://chat.googleapis.com/upload/v1/spaces/AAAA/attachments:upload",
      { method: "POST", body: new TextEncoder().encode("payload") },
      async () => `token-${++minted}`,
    );

    expect(response.status).toBe(200);
    expect(bodies).toEqual(["payload", "payload"]);
    expect(tokens).toEqual(["Bearer token-1", "Bearer token-2"]);
  });

  it("does not replay a 401 when the provider cannot refresh its token", async () => {
    let requests = 0;
    vi.stubGlobal("fetch", async () => { requests++; return new Response(null, { status: 401 }); });
    let response = await fetchWithAuthRetry("https://chat.googleapis.com/v1/spaces", {}, async () => "fixed");
    expect(response.status).toBe(401);
    expect(requests).toBe(1);
  });

  it("refreshes an invalidated profile token before checking the account subject", async () => {
    const provider = vi.fn(async (opts?: AccessTokenRequest) => opts?.forceRefresh ? "fresh" : "stale");
    vi.stubGlobal("fetch", async (_input: string, init: RequestInit) =>
      new Headers(init.headers).get("Authorization") === "Bearer fresh"
        ? Response.json({sub: "original-account"}) : new Response(null, {status: 401}));
    expect(await getGoogleAccountProfile(provider)).toEqual({sub: "original-account"});
    expect(provider).toHaveBeenLastCalledWith({forceRefresh: true, staleToken: "stale"});
  });
});

