describe("indexed field names", () => {
  // Cloudflare indexes a caller's structured log fields under their bare name and only nests them
  // beneath `source` when returning them: `logger.warn(msg, {event: "x"})` is queried as `event`.
  // Confirmed two ways against the live API -- `/telemetry/keys` reports `event`/`component`/`level`
  // and no `source.*` key at all -- and by the docs' "Logging structured JSON objects" table, where
  // `console.log({user_id: 123})` is filterable as `user_id`.
  //
  // This is a regression guard for a real failure: discovery reported `source.event`, an agent
  // filtered on exactly what it had discovered, and the provider accepted the unknown key, matched
  // nothing, and returned an empty page with no error -- after scanning the full timeframe.
  const eventWithLogFields = {
    dataset: "cloudflare-workers",
    timestamp: 1,
    source: {
      level: "warn",
      component: "workshop.server",
      event: "user_do.reset.surfaced",
      exception: { name: "Error" },
    },
    $metadata: { id: "e1", service: "api-worker", level: "warn" },
  };

  function stubEvents(): { bodies: unknown[] } {
    const bodies: unknown[] = [];
    vi.stubGlobal("fetch", vi.fn(async (_input: string | URL | Request, init?: RequestInit) => {
      bodies.push(JSON.parse(String(init?.body)));
      return Response.json({
        success: true,
        result: {
          statistics: { elapsed: 0.01, rows_read: 1, bytes_read: 10 },
          events: { count: 1, events: [eventWithLogFields] },
        },
      });
    }));
    return { bodies };
  }

  it("maps a returned envelope path to the name the field is indexed under", () => {
    expect(observabilityFieldKey("source.event")).toBe("event");
    expect(observabilityFieldKey("source.exception.name")).toBe("exception.name");
    // Namespaces that really are addressed by their dotted path are left alone.
    expect(observabilityFieldKey("$metadata.service")).toBe("$metadata.service");
    expect(observabilityFieldKey("$workers.cpuTimeMs")).toBe("$workers.cpuTimeMs");
    expect(observabilityFieldKey("event")).toBe("event");
    // Only the leading segment is a prefix; an inner `source.` is part of the field name.
    expect(observabilityFieldKey("outer.source.event")).toBe("outer.source.event");
  });

  it("derives discoverable keys under their indexed names", async () => {
    stubEvents();
    const api = new CloudflareObservabilityApi(async () => "token", ACCOUNT_ID, "api-worker");

    const keys = (await api.listKeys()).map(entry => entry.key);

    expect(keys).toEqual(expect.arrayContaining([
      "event", "component", "level", "exception.name", "$metadata.service",
    ]));
    expect(keys.filter(key => key.startsWith("source."))).toEqual([]);
  });

  it("finds values for a field discovered under its indexed name", async () => {
    stubEvents();
    const api = new CloudflareObservabilityApi(async () => "token", ACCOUNT_ID, "api-worker");

    // The exact round trip that failed: discover `event`, then ask for its values.
    const values = await api.listValues("event", "string");

    expect(values).toEqual([expect.objectContaining({
      key: "event", value: "user_do.reset.surfaced",
    })]);
  });

  it("accepts the envelope path as an alias when reading values", async () => {
    stubEvents();
    const api = new CloudflareObservabilityApi(async () => "token", ACCOUNT_ID, "api-worker");

    // An agent that copied the path out of a `listEvents` result gets the same answer, reported
    // under the indexed name so the two spellings cannot diverge in later calls.
    const values = await api.listValues("source.event", "string");

    expect(values).toEqual([expect.objectContaining({
      key: "event", value: "user_do.reset.surfaced",
    })]);
  });

  it("rewrites a caller filter's envelope paths before sending them", async () => {
    const { bodies } = stubEvents();
    const api = new CloudflareObservabilityApi(async () => "token", ACCOUNT_ID, "api-worker");

    await api.listEvents({
      filter: {
        kind: "group",
        filterCombination: "and",
        filters: [
          { kind: "filter", key: "source.event", operation: "eq", type: "string", value: "x" },
          { kind: "filter", key: "$metadata.level", operation: "eq", type: "string", value: "warn" },
        ],
      },
    });

    expect(bodies).toHaveLength(1);
    expect(bodies[0]).toMatchObject({
      parameters: {
        filters: [
          // The binding's own scope condition is never rewritten.
          { key: "$metadata.service", operation: "eq", value: "api-worker" },
          {
            kind: "group",
            filters: [
              { key: "event", operation: "eq", value: "x" },
              { key: "$metadata.level", operation: "eq", value: "warn" },
            ],
          },
        ],
      },
    });
  });

  it("rewrites envelope paths in calculations and group-bys", async () => {
    const bodies: unknown[] = [];
    vi.stubGlobal("fetch", vi.fn(async (_input: string | URL | Request, init?: RequestInit) => {
      bodies.push(JSON.parse(String(init?.body)));
      return Response.json({
        success: true,
        result: {
          statistics: { elapsed: 0.01, rows_read: 1, bytes_read: 10 },
          calculations: [],
        },
      });
    }));
    const api = new CloudflareObservabilityApi(async () => "token", ACCOUNT_ID, "api-worker");

    await api.calculate({
      calculations: [{ operator: "uniq", key: "source.event", keyType: "string", alias: "kinds" }],
      groupBys: [{ value: "source.component", type: "string" }],
    });

    expect(bodies[0]).toMatchObject({
      parameters: {
        calculations: [{ operator: "uniq", key: "event", keyType: "string", alias: "kinds" }],
        groupBys: [{ value: "component", type: "string" }],
      },
    });
  });

  it("keeps a scope filter alongside a rewritten caller key", () => {
    const filter: ObservabilityFilter = {
      kind: "filter", key: "source.event", operation: "eq", type: "string", value: "x",
    };

    expect(scopeObservabilityFilters("api-worker", filter)).toEqual([
      { kind: "filter", key: "$metadata.service", operation: "eq", type: "string", value: "api-worker" },
      { kind: "filter", key: "event", operation: "eq", type: "string", value: "x" },
    ]);
  });
});

// Retrying a model request that failed transiently: runAgent runs the pass again even when the
// failed request already streamed output, and tells clients to discard that output first. Drives
// the real runAgent against a real OverseerImpl, with pi's faux provider standing in for the model.

import { describe, expect, it } from "vitest";
import { env } from "cloudflare:workers";
import { runInDurableObject } from "cloudflare:test";
import {
  createFauxCore, fauxAssistantMessage, fauxText, fauxThinking, type AssistantMessage,
} from "@earendil-works/pi-ai";
import type {
  AiChatAuthorInfo, AiChatMessage, AiChatMetadata, AiChatStreamEvent,
} from "@gadgets/workshop-shared/api";
import type { OverseerDurableObject } from "../src/overseer.js";
import type { GadgetRecord } from "../src/storage-schema/overseer-storage.js";
import { runAgent, type AgentHooks } from "../src/agent";

declare module "cloudflare:workers" {
  interface ProvidedEnv {
    TEST_OVERSEER: DurableObjectNamespace<OverseerDurableObject>;
  }
}

// The OverseerImpl members this test drives; the class itself is private to overseer.ts.
interface OverseerInternals extends AgentHooks {
  storage: {
    gadgets: { put(record: GadgetRecord): void };
    chatMeta: { put(meta: AiChatMetadata): void };
    chats: { put(message: AiChatMessage): void, list(): Iterable<AiChatMessage> };
  };
  nextChatSequence(chatId: number): number;
}

const OWNER: AiChatAuthorInfo = { type: "user", id: "owner@example.com", name: "Owner" };
const CHAT_ID = 1;

let doCounter = 0;

async function withImpl(fn: (impl: OverseerInternals) => Promise<void>): Promise<void> {
  let stub = env.TEST_OVERSEER.getByName(`agent-retry-${++doCounter}`);
  await runInDurableObject(stub, async (instance: OverseerDurableObject) => {
    await fn((instance as unknown as { impl: OverseerInternals }).impl);
  });
}

function seedChat(impl: OverseerInternals): void {
  impl.storage.gadgets.put({
    type: "gadget", id: 100, title: "App", created: new Date(0), bindingName: "APP",
    bindings: {},
  });
  impl.storage.chatMeta.put(
      { id: CHAT_ID, title: "Chat", started: new Date(0), lastActive: new Date(0) });
  impl.storage.chats.put({
    chatId: CHAT_ID, sequence: impl.nextChatSequence(CHAT_ID), timestamp: new Date(0),
    author: OWNER, type: "message", message: "Hi",
  });
}

// Runs one agent turn whose model answers each request with the next scripted response,
// returning the stream events sent to clients.
async function runScriptedTurn(
    impl: OverseerInternals, steps: AssistantMessage[]): Promise<AiChatStreamEvent[]> {
  let events: AiChatStreamEvent[] = [];
  impl.emitChatStreamEvent = (_chatId, event) => events.push(event);
  let faux = createFauxCore({ models: [{ id: "faux-model" }] });
  faux.setResponses(steps);
  await runAgent(impl, { model: faux.getModel(), stream: faux.stream }, CHAT_ID,
      { type: "agent", id: "faux-model", name: "Faux" }, new AbortController().signal, OWNER,
      { provider: "cloudflare", model: "faux-model", apiToken: "" });
  return events;
}

function streamedText(events: AiChatStreamEvent[]): string {
  return events.flatMap(event => event.type === "textDelta" ? [event.delta] : []).join("");
}

describe("transient model failures", () => {
  it("retries a request that failed after streaming output, discarding that output first",
      () => withImpl(async impl => {
    seedChat(impl);

    let events = await runScriptedTurn(impl, [
      fauxAssistantMessage([fauxThinking("Planning the answer"), fauxText("A partial ans")],
          { stopReason: "error", errorMessage: "503 Service Unavailable" }),
      fauxAssistantMessage(fauxText("The full answer.")),
    ]);

    // The failed attempt's output streamed, then clients were told to drop it before the retry
    // streamed its own.
    let reset = events.findIndex(event => event.type === "streamReset");
    expect(reset).toBeGreaterThan(0);
    expect(events.filter(event => event.type === "streamReset")).toHaveLength(1);
    expect(streamedText(events.slice(0, reset))).toBe("A partial ans");
    expect(streamedText(events.slice(reset + 1))).toBe("The full answer.");

    // Only the retry's answer is persisted, and the turn ended without an error.
    let messages = [...impl.storage.chats.list()].filter(msg => msg.chatId === CHAT_ID);
    expect(messages.filter(msg => msg.type === "error")).toEqual([]);
    expect(messages.flatMap(msg => msg.type === "message" ? [msg.message] : []))
        .toEqual(["Hi", "The full answer."]);
  }));

  it("does not retry a failure that isn't transient", () => withImpl(async impl => {
    seedChat(impl);

    await expect(runScriptedTurn(impl, [
      fauxAssistantMessage(fauxText("A partial ans"),
          { stopReason: "error", errorMessage: "400 Invalid request" }),
      fauxAssistantMessage(fauxText("Never requested.")),
    ])).rejects.toThrow("400 Invalid request");
  }));
});

import {env} from "cloudflare:workers";
